// Command genpython embeds the bitmap schema into the databricks-bundles Python
// decoder (python/databricks/bundles/_bitmap/_schema.py), compressed. It
// compresses in Go rather than in Python because Python builds link different
// zlib implementations whose output differs, while compress/flate is the same
// everywhere, so the generated file does not depend on who ran the generator.
package main

import (
	"bytes"
	"compress/flate"
	"encoding/base64"
	"fmt"
	"os"
	"strings"

	"github.com/databricks/cli/bundle/bitmap"
)

const header = `# Code generated by bundle/bitmap/genpython from bundle/bitmap/schema.txt. DO NOT EDIT.
# Regenerate with './task generate-bitmap-schema'.

import base64
import zlib

# Raw DEFLATE of the schema, one field path per line.
_COMPRESSED = (
`

const footer = `)

SCHEMA: list[str] = zlib.decompress(base64.b64decode(_COMPRESSED), -15).decode().split()
`

// lineWidth keeps each string literal within the repo's ruff line length.
const lineWidth = 100

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: genpython OUTPUT_PY")
		os.Exit(2)
	}
	if err := generate(os.Args[1]); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func generate(path string) error {
	var compressed bytes.Buffer
	w, err := flate.NewWriter(&compressed, flate.BestCompression)
	if err != nil {
		return err
	}
	if _, err := w.Write([]byte(strings.Join(bitmap.EmbeddedSchema(), "\n") + "\n")); err != nil {
		return err
	}
	if err := w.Close(); err != nil {
		return err
	}
	encoded := base64.StdEncoding.EncodeToString(compressed.Bytes())

	var out strings.Builder
	out.WriteString(header)
	for len(encoded) > 0 {
		n := min(lineWidth, len(encoded))
		fmt.Fprintf(&out, "    %q\n", encoded[:n])
		encoded = encoded[n:]
	}
	out.WriteString(footer)
	return os.WriteFile(path, []byte(out.String()), 0o644)
}
